Newton–Raphson in R


Code
newton &lt;- function(S, dS, x0, tol = 1e-8, maxit = 100, trace = FALSE) {
  for (k in 1:maxit) {
    x1 &lt;- x0 - S(x0) / dS(x0)
    if (trace) cat(sprintf("iter %2d: %.10f\n", k, x1))
    if (!is.finite(x1)) stop("diverged")
    if (abs(x1 - x0) &lt; tol) return(c(root = x1, iter = k))
    x0 &lt;- x1 }
  stop("not converged")
}
